  'escrow.fees.example': 'Example: a 100 POL escrow with 2 arbitrators settles 99.00 POL to the receiver, 0.50 POL to the manager and 0.25 POL to each arbitrator.',
  'escrow.trace.title': 'Transparency and traceability',
